macro_rules! deps {
    () => {
        Span!();
        Regex!();
        Anchored!();
    };
}

macro_rules! Input {
    () => {
        deps!();
        # [doc = " The parameters for a regex search including the haystack to search."] # [doc = ""] # [doc = " It turns out that regex searches have a few parameters, and in most cases,"] # [doc = " those parameters have defaults that work in the vast majority of cases."] # [doc = " This `Input` type exists to make that common case seamless while also"] # [doc = " providing an avenue for changing the parameters of a search. In particular,"] # [doc = " this type enables doing so without a combinatorial explosion of different"] # [doc = " methods and/or superfluous parameters in the common cases."] # [doc = ""] # [doc = " An `Input` permits configuring the following things:"] # [doc = ""] # [doc = " * Search only a substring of a haystack, while taking the broader context"] # [doc = " into account for resolving look-around assertions."] # [doc = " * Indicating whether to search for all patterns in a regex, or to"] # [doc = " only search for one pattern in particular."] # [doc = " * Whether to perform an anchored on unanchored search."] # [doc = " * Whether to report a match as early as possible."] # [doc = ""] # [doc = " All of these parameters, except for the haystack, have sensible default"] # [doc = " values. This means that the minimal search configuration is simply a call"] # [doc = " to [`Input::new`] with your haystack. Setting any other parameter is"] # [doc = " optional."] # [doc = ""] # [doc = " Moreover, for any `H` that implements `AsRef<[u8]>`, there exists a"] # [doc = " `From<H> for Input` implementation. This is useful because many of the"] # [doc = " search APIs in this crate accept an `Into<Input>`. This means you can"] # [doc = " provide string or byte strings to these routines directly, and they'll"] # [doc = " automatically get converted into an `Input` for you."] # [doc = ""] # [doc = " The lifetime parameter `'h` refers to the lifetime of the haystack."] # [doc = ""] # [doc = " # Organization"] # [doc = ""] # [doc = " The API of `Input` is split into a few different parts:"] # [doc = ""] # [doc = " * A builder-like API that transforms a `Input` by value. Examples:"] # [doc = " [`Input::span`] and [`Input::anchored`]."] # [doc = " * A setter API that permits mutating parameters in place. Examples:"] # [doc = " [`Input::set_span`] and [`Input::set_anchored`]."] # [doc = " * A getter API that permits retrieving any of the search parameters."] # [doc = " Examples: [`Input::get_span`] and [`Input::get_anchored`]."] # [doc = " * A few convenience getter routines that don't conform to the above naming"] # [doc = " pattern due to how common they are. Examples: [`Input::haystack`],"] # [doc = " [`Input::start`] and [`Input::end`]."] # [doc = " * Miscellaneous predicates and other helper routines that are useful"] # [doc = " in some contexts. Examples: [`Input::is_char_boundary`]."] # [doc = ""] # [doc = " A `Input` exposes so much because it is meant to be used by both callers of"] # [doc = " regex engines _and_ implementors of regex engines. A constraining factor is"] # [doc = " that regex engines should accept a `&Input` as its lowest level API, which"] # [doc = " means that implementors should only use the \"getter\" APIs of a `Input`."] # [doc = ""] # [doc = " # Valid bounds and search termination"] # [doc = ""] # [doc = " An `Input` permits setting the bounds of a search via either"] # [doc = " [`Input::span`] or [`Input::range`]. The bounds set must be valid, or"] # [doc = " else a panic will occur. Bounds are valid if and only if:"] # [doc = ""] # [doc = " * The bounds represent a valid range into the input's haystack."] # [doc = " * **or** the end bound is a valid ending bound for the haystack *and*"] # [doc = " the start bound is exactly one greater than the start bound."] # [doc = ""] # [doc = " In the latter case, [`Input::is_done`] will return true and indicates any"] # [doc = " search receiving such an input should immediately return with no match."] # [doc = ""] # [doc = " Note that while `Input` is used for reverse searches in this crate, the"] # [doc = " `Input::is_done` predicate assumes a forward search. Because unsigned"] # [doc = " offsets are used internally, there is no way to tell from only the offsets"] # [doc = " whether a reverse search is done or not."] # [doc = ""] # [doc = " # Regex engine support"] # [doc = ""] # [doc = " Any regex engine accepting an `Input` must support at least the following"] # [doc = " things:"] # [doc = ""] # [doc = " * Searching a `&[u8]` for matches."] # [doc = " * Searching a substring of `&[u8]` for a match, such that any match"] # [doc = " reported must appear entirely within that substring."] # [doc = " * For a forwards search, a match should never be reported when"] # [doc = " [`Input::is_done`] returns true. (For reverse searches, termination should"] # [doc = " be handled outside of `Input`.)"] # [doc = ""] # [doc = " Supporting other aspects of an `Input` are optional, but regex engines"] # [doc = " should handle aspects they don't support gracefully. How this is done is"] # [doc = " generally up to the regex engine. This crate generally treats unsupported"] # [doc = " anchored modes as an error to report for example, but for simplicity, in"] # [doc = " the meta regex engine, trying to search with an invalid pattern ID just"] # [doc = " results in no match being reported."] # [derive (Clone)] pub struct Input < 'h > { haystack : & 'h [u8] , span : Span , anchored : Anchored , earliest : bool , }
    };
}

Input!();